WITH sales_agg AS ( SELECT w.w_state, td.t_shift, p.p_promo_name, SUM(cs.cs_net_profit) AS total_profit, AVG(cs.cs_sales_price) AS avg_sales_price, SUM(cs.cs_ext_discount_amt) AS total_discount, COUNT(*) AS num_transactions FROM catalog_sales cs JOIN time_dim td ON cs.cs_sold_time_sk = td.t_time_sk JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk WHERE p.p_discount_active = 'Y' AND cs.cs_quantity > 5 AND cs.cs_sold_date_sk BETWEEN 2450820 AND 2450825 AND cs.cs_sold_date_sk BETWEEN p.p_start_date_sk AND p.p_end_date_sk AND td.t_hour BETWEEN 9 AND 17 GROUP BY w.w_state, td.t_shift, p.p_promo_name HAVING SUM(cs.cs_net_profit) > 10000 ) SELECT s.w_state, s.t_shift, s.p_promo_name, s.total_profit, s.avg_sales_price, s.total_discount, s.num_transactions, RANK() OVER (PARTITION BY s.w_state ORDER BY s.total_profit DESC) AS profit_rank_state FROM sales_agg s ORDER BY s.total_profit DESC LIMIT 20
